{
  "iteration": 10,
  "pcvs": [
    {
      "name": "penalty_batch_size",
      "expression": "logits.shape[0] if not sampling_metadata.no_penalties else 0",
      "rationale": "Captures the dominant batch-dependent penalty cost."
    },
    {
      "name": "requests_without_output",
      "expression": "sum(int(len(row) == 0) for row in sampling_metadata.output_token_ids)",
      "rationale": "Retains the feature consistently associated with substantially better penalty attribution."
    },
    {
      "name": "unpenalized_mask_active",
      "expression": "int(sampling_metadata.no_penalties and sum(len(getattr(processor, 'logits_slice', ([], []))[0]) for processor in sampling_metadata.logitsprocs.non_argmax_invariant) > 0)",
      "rationale": "Separately captures activation of masking in unpenalized calls."
    },
    {
      "name": "unpenalized_single_mask",
      "expression": "int(sampling_metadata.no_penalties and sum(len(getattr(processor, 'logits_slice', ([], []))[0]) for processor in sampling_metadata.logitsprocs.non_argmax_invariant) == 1)",
      "rationale": "Allows an independent contribution for the more expensive singleton masking case."
    }
  ],
  "hypothesis": "Dropping the fixed penalty indicator frees a feature for independently fitting singleton masking. Batch size and empty-history cardinality retain the dominant penalty predictors, while separate masking indicators avoid imposing an inaccurate cost ratio."
}
